package workbench

func addWorkbenchImprovementDetails(id string, schema map[string]any) bool {
	switch id {
	case "component.explain":
		schema["x-command-contract"] = commandContractDetail{Version: 1, Scope: "component-explanation", Preconditions: []string{"Exact current component ID; no mutation key/revision guard required"}, Effects: []string{"Pure owned query; selected component has the same explanation in project.inspect.component_explanation", "Separates current/stale/unavailable accepted readings and structural facts from generic educational model advice; recorded data never substitutes live facts", "Returns relevant existing diagnostic associations and published model limits; does not guess a solver failure's physical cause or validate real hardware"}, Errors: []commandFailureDetail{{"not-found", "query", "Component no longer exists"}, {"invalid-params", "query", "Malformed input"}}, Completion: &commandCompletionDetail{Mode: "immediate pure query"}}
	case "scope.probe.plot":
		schema["x-command-contract"] = commandContractDetail{Version: 1, Scope: "plot-live-probe", Preconditions: []string{"A transient circuit exists; exact ID from snapshot.scope.available; ordinary revision/document/key guards apply"}, Effects: []string{"Atomically adds the source without duplicates, reveals live scope and highlights its schematic association", "Preserves every requested trace, including missing-source slots; refuses a seventh slot without mutation. Use scope.probe.remove to make room", "Returns recorded viewer to live and stops its playback, preserving selected capture, rows, cursors and window; a later import cannot steal this choice", "Preserves graph, accepted physics/time, pause, run/electrical revision and edit history; selecting a source does not simulate a new sample"}, Errors: []commandFailureDetail{{"not-ready", "admission", "No transient circuit"}, {"not-found", "admission", "Unknown current probe"}, {"invalid-params", "admission", "Malformed input or all six slots full"}}, Completion: &commandCompletionDetail{Mode: "immediate presentation update"}}
	case "edit.proposal.apply", "edit.proposal.dismiss":
		schema["x-command-contract"] = commandContractDetail{Version: 1, Scope: "reviewed-edit-proposal", Preconditions: []string{"Exact current snapshot.edit_proposal.id and ordinary mutation guards/key; document replacement retires it"}, Effects: []string{"Dismiss clears only the session proposal. Apply requires unchanged graph/settings/lifetime ID reservations, then revalidates the same batch through edit.batch admission", "An actual applied content change is one Undo entry with the supplied batch name and applying actor. Existing electrical restart/paused-stale and history-ownership rules apply", "Failed or stale application preserves circuit and proposal. Successful application clears the proposal; successful retry returns its owned original response without reapplying"}, Errors: []commandFailureDetail{{"conflict", "admission", "Proposal ID/document changed, or applying a stale source"}, {"invalid-params", "admission", "Malformed input or current batch validation failure"}}, Completion: &commandCompletionDetail{Mode: "immediate guarded apply/dismiss; existing asynchronous simulation readiness"}}
	default:
		return false
	}
	return true
}
